// Question bank for exam2Content. Returns {CASES, Q, SECTIONS}.
export default function exam2Content(){
/* ---------- Content ---------- */
const DOMAINS={1:"Implement and manage an analytics solution",2:"Ingest and transform data",3:"Monitor and optimize an analytics solution"};

const CASE={
  title:"Case study: Tamarack Energy Cooperative",
  tabs:[
   {name:"Overview",html:`<p>Tamarack Energy is a rural electric cooperative that serves 310,000 smart meters across four regions: North, South, East, and West. A central data team of eight people is standardizing analytics on Microsoft Fabric. The Finance and Operations departments each want to govern their own workspaces.</p>`},
   {name:"Existing environment",html:`<h4>Fabric</h4><ul><li>Two capacities: <code>CAP-Prod</code> (F128) and <code>CAP-Dev</code> (F16).</li><li>Three workspaces: <code>TE-Dev</code>, <code>TE-Test</code>, and <code>TE-Prod</code>.</li><li><code>TE-Prod</code> contains lakehouse <code>LH_Meters</code>, warehouse <code>WH_Finance</code>, and Eventhouse <code>EH_Grid</code>.</li><li>Tenant admins want to delegate some tenant settings to Finance and Operations without making anyone a capacity admin.</li></ul>
<h4>Data sources</h4><ul><li><b>Meter telemetry</b>: JSON events sent to Azure Event Hubs at about 20,000 events per second.</li><li><b>Billing</b>: an Azure Database for PostgreSQL flexible server.</li><li><b>Outage tickets</b>: Dataverse tables.</li><li><b>Weather observations</b>: hourly CSV files that a vendor writes to an Azure Data Lake Storage Gen2 account the vendor owns. The vendor provides a service principal for access.</li><li><b>Orchestration</b>: about 40 Apache Airflow DAGs written in Python on an on-premises Airflow server.</li></ul>`},
   {name:"Requirements",html:`<h4>Business</h4><ul><li>Operations must receive a Teams message within one minute when any meter reports voltage above 253 V.</li><li>Regional analysts must see only meters in their own region.</li></ul>
<h4>Technical</h4><ul><li>Billing data must be available in OneLake with minimal latency and no custom ETL to maintain.</li><li>Weather data must not be copied into OneLake until it's transformed.</li><li>All items must be version-controlled in GitHub and promoted Dev → Test → Prod with a deployment pipeline.</li><li>Each stage must use its own connections and lakehouse references. These values must be managed centrally and tracked in Git.</li><li>Warehouse schema changes must be reviewed in pull requests. Warehouse object permissions must be deployed together with the schema.</li><li>Airflow DAGs must be migrated with minimal rewriting and must authenticate to Fabric without storing secrets.</li></ul>
<h4>Security</h4><ul><li>Regional analysts use Spark notebooks and Power BI. They must hold only the Viewer role on <code>TE-Prod</code>.</li><li>Follow the principle of least privilege.</li></ul>
<h4>Operations</h4><ul><li>During the 2:00 AM nightly loads, report users on <code>CAP-Prod</code> experience 20-second delays. The nightly loads must not be rejected.</li></ul>`}
  ]
};

const Q=[
/* ===== Section 1: case study ===== */
{s:0,d:2,t:"single",ref:"mirroring Azure Database for PostgreSQL Fabric",
 stem:`You need to meet the technical requirement for billing data. What should you implement?`,
 opts:["A Copy job that runs every five minutes","Mirroring for Azure Database for PostgreSQL","An Eventstream with a PostgreSQL CDC source and a lakehouse destination","A Dataflow Gen2 with incremental refresh"],a:1,
 ex:`Mirroring continuously replicates the PostgreSQL tables into Delta tables in OneLake with no pipeline or dataflow to maintain. An Eventstream CDC source delivers change events that you'd still have to shape into tables, and a Copy job or dataflow is scheduled ETL with higher latency.`},
{s:0,d:1,t:"hot",ref:"variable library value sets deployment pipeline",
 stem:`You need to meet the requirement for per-stage connections and lakehouse references. How should you complete the design? Select the appropriate option in each list.`,
 tpl:`Item that holds the values:            [[0]]
Per-stage values are stored as:        [[1]]
After the first deployment to TE-Test,
the active set in TE-Test is:          [[2]] until someone changes it`,
 sel:[["Variable library","Deployment rule","Environment"],["Value sets","Parameters","Connections"],["Default","Test","The set that was active in Dev"]],a:[0,0,0],
 ex:`A variable library holds connection reference and item reference variables with one value set per stage. All value sets deploy to every stage, but a newly created stage starts with the Default set active, and later deployments never change the active set.`},
{s:0,d:1,t:"yesno",ref:"OneLake security row-level security Spark Viewer",
 stem:`You are designing security for the regional analysts. For each statement, select Yes if it is true. Otherwise, select No.`,
 rows:["You can meet the requirement by creating a OneLake security role on LH_Meters that grants Read on the Meters table with a row-level security rule on the Region column.","Row-level security defined in the SQL analytics endpoint is also enforced when analysts read the table from a Spark notebook.","The analysts must be assigned the Contributor role for the OneLake security role to take effect."],a:[1,0,0],
 ex:`OneLake security roles are enforced across Fabric engines, including Spark. SQL analytics endpoint RLS applies only to T-SQL queries. OneLake security roles apply to Viewers and users with Read permission; Admins, Members, and Contributors already have full data access and bypass the roles.`},
{s:0,d:1,t:"single",ref:"Fabric warehouse Git integration post-deployment script permissions database project",
 stem:`You need to meet the requirement for warehouse object permissions. What should you do?`,
 opts:["Add GRANT statements to the table definition files in the database project","Add a post-deployment script to the warehouse's SQL database project","Create a deployment rule for WH_Finance in the deployment pipeline","Nothing. Permissions are committed with the warehouse definition"],a:1,
 ex:`Warehouse Git integration commits the schema as a database project, but SQL security such as permissions isn't captured. Microsoft's guidance is to put the GRANT statements in a post-deployment script (stored in the .sharedqueries folder) so they deploy with the schema.`},
{s:0,d:1,t:"multi",n:2,ref:"Apache Airflow job workspace identity Fabric connection",
 stem:`You need to meet the requirements for the Airflow DAGs. Which two actions should you perform? Each correct answer presents part of the solution.`,
 opts:["Create an Apache Airflow job item in TE-Prod and add the DAG files","Enable the workspace identity and create a Fabric connection that uses workspace identity authentication with Allow Code-First Artifacts selected","Rebuild each DAG as a Data pipeline","Store a service principal secret as a variable in each DAG","Create one Spark job definition per DAG"],a:[0,1],
 ex:`An Apache Airflow job runs existing Python DAGs natively. Workspace identity lets the DAGs authenticate to Fabric items without secrets. The Allow Code-First Artifacts option must be selected when the connection is created, because it can't be changed later.`},
{s:0,d:3,t:"multi",n:2,ref:"Fabric capacity interactive delay throttling scale up scale out",
 stem:`You need to resolve the delays that report users experience at 2:00 AM while meeting the operations requirement. Which two actions should you perform? Each correct answer presents a complete solution.`,
 opts:["Enable capacity-level surge protection on CAP-Prod with a 60% background rejection threshold","Move the workspaces that run the nightly loads to a separate capacity","Scale up CAP-Prod during the load window","Set the Spark session timeout to 5 minutes","Enable result set caching on WH_Finance"],a:[1,2],
 ex:`The 20-second delays are interactive delay throttling: the nightly background jobs consumed the next 10 minutes of capacity. Scaling up or scaling out removes the overload. Surge protection would reject new background operations, which violates the requirement that nightly loads must not be rejected.`},
{s:0,d:2,t:"build",ref:"ADLS Gen2 shortcut service principal Files section lakehouse",
 stem:`You need to make the weather data available to analysts while meeting the technical requirement. Which four actions should you perform in sequence? Move the appropriate actions to the answer area and arrange them in the correct order.`,
 pool:["Create a cloud connection to the vendor's ADLS Gen2 account that authenticates with the vendor's service principal","Create an ADLS Gen2 shortcut in the Files section of LH_Meters","Transform the CSV files in a notebook and write a Delta table to the Tables section","Grant analysts access to the weather table through a OneLake security role","Create the shortcut in the Tables section of LH_Meters","Copy the CSV files into OneLake with a Copy activity"],a:[0,1,2,3],
 ex:`A shortcut reads the vendor files in place, so nothing is copied until the notebook writes the transformed Delta table. CSV files belong in Files; the Tables section only recognizes Delta data. Copying the raw CSV would violate the requirement.`},
{s:0,d:1,t:"single",ref:"Fabric domains delegate tenant settings domain admin",
 stem:`You need to meet the requirement to delegate tenant settings to Finance and Operations. What should you do?`,
 opts:["Create a domain per department, assign the workspaces, and delegate the settings","Create a capacity for each department, move the workspaces, and delegate the settings","Assign the department leads the Admin role on each of their workspaces","Add the department leads to the Fabric administrator role in Microsoft Entra ID"],a:0,
 ex:`Domains group workspaces logically and have domain admins who can override delegated tenant settings. A setting can be delegated through domains or through capacities, but not both. Capacities would require capacity admins, and workspace or tenant admin roles are either too narrow or too broad.`},

/* ===== Section 2: main ===== */
{s:1,d:1,t:"hot",ref:"Spark workspace settings session timeout maximum job lifetime",
 stem:`Interactive Spark sessions in Workspace1 stay alive after users stop working and consume capacity. You need sessions to expire after 10 minutes of inactivity, and you need to stop any user-submitted job that runs longer than four hours. How should you complete the configuration? Select the appropriate option in each list.`,
 tpl:`Workspace settings > Data Engineering/Science > Spark settings > [[0]] tab
  Spark session timeout:      [[1]]
  Set maximum job lifetime:   4 hours   (applies to [[2]])`,
 sel:[["Jobs","Pool","High concurrency"],["10 minutes","2 minutes","20 minutes"],["user-submitted jobs only","all jobs, including OPTIMIZE and VACUUM","notebooks only"]],a:[0,0,0],
 ex:`Both settings live on the Jobs tab. The default session timeout is 20 minutes. Maximum job lifetime applies only to user-submitted jobs (notebooks, Spark job definitions, Livy sessions); system-managed jobs such as table maintenance and materialized lake view refreshes aren't affected.`},
{s:1,d:1,t:"single",ref:"Fabric Spark compute capacity vCores node limits F64",
 stem:`Workspace1 is on an F64 capacity. You create a custom Spark pool that uses Large nodes (16 vCores each). What is the maximum number of nodes the pool can have?`,
 opts:["4","8","16","32"],a:1,
 ex:`One capacity unit equals two Spark vCores, so F64 provides 128 Spark vCores. 128 ÷ 16 vCores per Large node = 8 nodes.`},
{s:1,d:1,t:"yesno",ref:"Fabric starter pool managed private endpoint autopause high concurrency",
 stem:`For each statement about Spark in Fabric, select Yes if it is true. Otherwise, select No.`,
 rows:["Starter pools can be used in a workspace that has managed private endpoints.","The autopause interval after a session expires can be changed in the workspace Spark settings.","By default, a high concurrency session can be shared by up to five notebooks."],a:[0,0,1],
 ex:`Workspaces with managed private endpoints or Private Link require custom pools. Autopause is fixed at two minutes after session expiry. The default session sharing limit is five notebooks; raise it with spark.highConcurrency.max in an environment.`},
{s:1,d:3,t:"single",ref:"Fabric Spark resource profiles readHeavyForPBI writeHeavy",
 stem:`A gold-layer lakehouse is read mostly by Power BI Direct Lake semantic models. You want new tables written with V-Order enabled and large files by default. Which resource profile should you set in the environment?`,
 opts:["writeHeavy","readHeavyForPBI","readHeavyForSpark","A custom profile with spark.sql.parquet.vorder.default set to false"],a:1,
 ex:`readHeavyForPBI enables V-Order and uses a 1 GB optimize-write bin size, which suits Direct Lake reads. writeHeavy disables V-Order for ingestion speed. Set spark.fabric.resourceProfile in the environment; a runtime spark.conf.set overrides it.`},
{s:1,d:1,t:"single",ref:"Apache Airflow job enable triggers deferrable operators",
 stem:`A DAG in an Apache Airflow job uses deferrable operators and fails with a trigger-related error. What should you do?`,
 opts:["Enable triggers in the Airflow job's Environment configuration","Grant the DAG's service principal the Item.Execute.All permission","Enable high concurrency mode for the notebooks in the same workspace","Attach the Airflow job to a custom Spark pool in the same workspace"],a:0,
 ex:`Deferrable operators need the Airflow triggerer component, which is enabled from the Airflow job's Environment configuration settings.`},
{s:1,d:1,t:"single",ref:"OneLake user-delegated SAS tokens workspace delegated settings",
 stem:`An application outside Fabric must read a lakehouse by using a short-lived token that's based on a user's Microsoft Entra identity and that can't live longer than one hour. Which workspace setting must be enabled?`,
 opts:["Enable Authenticate with OneLake user-delegated SAS tokens","Users can sync data in OneLake with the OneLake File Explorer app","Trusted workspace access for the external application's connection","Git integration for the workspace that contains the lakehouse"],a:0,
 ex:`OneLake user-delegated SAS tokens are signed with a user delegation key and are limited to one hour. The tenant setting for short-lived SAS tokens must also be on. File Explorer sync and trusted workspace access solve different problems.`},
{s:1,d:1,t:"match",ref:"Fabric Git integration branch out switch branch checkout new branch update all",
 stem:`Match each goal to the Source control action. Each action may be used once, more than once, or not at all.`,
 targets:["Work in isolation on a copy of the workspace that's tied to a new Git branch","Replace every item in the current workspace with the content of another branch","Connect the current workspace to a new branch while keeping its current content","Pull commits that teammates merged into the connected branch"],
 pool:["Branch out to another workspace","Switch branch","Checkout new branch","Update all","Commit","Deploy"],a:[0,1,2,3],
 ex:`Branch out creates a new branch and workspace. Switch branch overwrites the workspace with the selected branch. Checkout new branch keeps the workspace state and only changes the connection. Update all pulls from Git.`},
{s:1,d:1,t:"yesno",ref:"Allow users with at least Contributor role to change Git branch conflicts",
 stem:`For each statement about Git integration, select Yes if it is true. Otherwise, select No.`,
 rows:["A Contributor can switch the workspace's Git branch when the workspace setting Allow users with at least Contributor role to change Git branch is enabled and the Contributor has write access to all items.","When you switch branches, items that exist only in the workspace and were never committed are preserved.","If the same item changed in both the workspace and the Git branch, Update is disabled until the conflict is resolved."],a:[1,0,1],
 ex:`Branch switching is admin-only unless the workspace setting delegates it. Switching overrides all items with the branch content, and you can't switch with uncommitted changes. Conflicts on the same item block updates until resolved.`},
{s:1,d:1,t:"single",ref:"Fabric warehouse Git integration limitations SQL analytics endpoint",
 stem:`Which object is NOT version-controlled by Fabric Git integration?`,
 opts:["A table in the warehouse's dbo schema","A stored procedure in the same warehouse","A lakehouse SQL analytics endpoint view","A view in the warehouse's dbo schema"],a:2,
 ex:`Warehouse objects are committed as a database project. Version control for SQL analytics endpoints isn't available, and warehouse permissions need a post-deployment script.`},
{s:1,d:1,t:"single",ref:"variable library item reference variable notebook lakehouse",
 stem:`A notebook in the staging workspace writes to a lakehouse in the presentation workspace. The target lakehouse differs in Dev, Test, and Prod. You need the notebook to resolve the correct lakehouse per stage without editing code after each deployment. What should you use?`,
 opts:["A connection reference variable in a variable library","An item reference variable in a variable library","A Spark environment property","A pipeline parameter with a default value"],a:1,
 ex:`Item reference variables store a workspace ID and item ID per value set, so the notebook reads the right lakehouse for the active stage. Connection reference variables parameterize external data source connections.`},
{s:1,d:1,t:"match",ref:"Fabric item permissions Build ReadData ReadAll OneLake security ReadWrite",
 stem:`Match each access requirement to the permission. Each permission may be used once, more than once, or not at all.`,
 targets:["Build Power BI reports on a semantic model without reading the underlying lakehouse","Query a warehouse with T-SQL only","Read all lakehouse files and tables through Spark","Let a Viewer write to one folder through the OneLake APIs"],
 pool:["Build permission on the semantic model","Share the warehouse with Read all data using SQL (ReadData)","Share the lakehouse with Read all Apache Spark (ReadAll)","A OneLake security role with ReadWrite on the folder","Contributor workspace role","Reshare permission"],a:[0,1,2,3],
 ex:`Build is a semantic model permission. ReadData grants SQL endpoint access only, ReadAll grants OneLake/Spark access, and OneLake security ReadWrite gives read-only users write access to specific folders or tables.`},
{s:1,d:1,t:"single",ref:"OneLake security multiple roles column-level security evaluate",
 stem:`User1 is a Viewer and belongs to two OneLake security roles on Lakehouse1. RoleA grants Read on the Sales table and hides the Salary column. RoleB grants Read on the Sales table with no column rules. What can User1 see?`,
 opts:["All columns, including Salary","All columns except Salary","Nothing; the conflicting roles cancel each other","An error until one role is removed"],a:0,
 ex:`OneLake security uses a grant-only model. Hiding a column in one role doesn't deny access that another role grants, so User1 sees Salary through RoleB.`},
{s:1,d:1,t:"hot",ref:"column-level security dynamic data masking partial Fabric warehouse",
 stem:`Analysts must never see the Salary column in dbo.Employee, and the Phone column must display as XXX-XXX-1234 for users without UNMASK. How should you complete the T-SQL? Select the appropriate option in each list.`,
 tpl:`[[0]] SELECT ON dbo.Employee (EmployeeId, Name, Region, Phone) TO Analysts;

ALTER TABLE dbo.Employee
  ALTER COLUMN Phone ADD MASKED WITH (FUNCTION = '[[1]]');`,
 sel:[["GRANT","DENY","REVOKE"],["partial(0, \"XXX-XXX-\", 4)","email()","default()"]],a:[0,0],
 ex:`Column-level security is implemented by granting SELECT on an explicit column list; referencing Salary then raises an error. partial(prefix, padding, suffix) exposes no leading characters, inserts the padding, and shows the last four characters.`},
{s:1,d:2,t:"yesno",ref:"Fabric warehouse primary key not enforced default constraints",
 stem:`For each statement about table constraints in Fabric Warehouse, select Yes if it is true. Otherwise, select No.`,
 rows:["You can declare a PRIMARY KEY inline in a CREATE TABLE statement.","FOREIGN KEY constraints must be created with the NOT ENFORCED option.","DEFAULT constraints are supported."],a:[0,1,0],
 ex:`Primary, unique, and foreign key constraints are added with ALTER TABLE, not inline, and only as NOT ENFORCED (primary key and unique also NONCLUSTERED). Default constraints aren't supported.`},
{s:1,d:1,t:"match",ref:"Fabric endorsement promoted certified master data sensitivity label",
 stem:`Match each goal to the governance feature. Each feature may be used once, more than once, or not at all.`,
 targets:["Flag an item as the authoritative source for core business entities such as customers and products","Let any item owner signal that an item is ready for others to use","Limit the endorsement to a reviewer group that the admin configures","Classify an item so that protection follows its data when it's exported to Excel"],
 pool:["Master data endorsement","Promoted endorsement","Certified endorsement","Sensitivity label","Featured","Domain"],a:[0,1,2,3],
 ex:`Promoted can be applied by anyone with write permission. Certified and Master data are restricted to users the admin authorizes. Sensitivity labels come from Microsoft Purview and travel with exported data.`},
{s:1,d:1,t:"single",ref:"Fabric audit log Purview OneLake security role changes",
 stem:`Compliance asks who created or changed OneLake security roles on Lakehouse1 last month. Where should you look?`,
 opts:["The Fabric audit log in Microsoft Purview","The OneLake diagnostics lakehouse for the workspace","The Capacity Metrics app for the last 14 days","The Monitoring hub, filtered to Lakehouse1 activity"],a:0,
 ex:`Control-plane activities such as changes to security roles, shortcuts, and sharing are in the Fabric audit log. OneLake diagnostics records data-plane access through OneLake APIs.`},
{s:1,d:1,t:"yesno",ref:"Get-PowerBIActivityEvent audit log Exchange Online role OneLake diagnostics",
 stem:`For each statement about auditing, select Yes if it is true. Otherwise, select No.`,
 rows:["Get-PowerBIActivityEvent can return at most one day of activity per call.","Searching the audit log in Purview requires the Audit Logs role in Exchange Online.","OneLake diagnostics events are stored in an Eventhouse."],a:[1,1,0],
 ex:`The cmdlet and the ActivityEvents API are limited to one day per request and handle continuation tokens. Purview audit search needs the Exchange Online Audit Logs role. OneLake diagnostics writes events to a lakehouse that you select.`},
{s:1,d:1,t:"hot",ref:"pipeline event trigger OneLake events Activator Subject filter",
 stem:`A pipeline must start whenever a file lands under the /raw/orders/ folder of a lakehouse. How should you complete the configuration? Select the appropriate option in each list.`,
 tpl:`Pipeline canvas > Home > [[0]]
  Event source:   [[1]] events
  Filter:         Subject contains "/raw/orders/"   (the Subject field carries [[2]])
  Action:         Run a Fabric item > the pipeline`,
 sel:[["Trigger","Schedule","Run"],["OneLake","Workspace item","Job"],["folder and file names","event types","capacity names"]],a:[0,0,0],
 ex:`The Trigger button opens the Set alert panel, which creates an Activator rule and an eventstream. OneLake events cover file created and deleted events, and the Subject field holds the container, folder, and file name for filtering.`},
{s:1,d:1,t:"single",ref:"pipeline expression concat pipeline parameters dynamic content",
 stem:`A pipeline has a string parameter named LoadDate. The Copy activity's source query must return rows where OrderDate equals LoadDate. Which expression is valid?`,
 opts:[`@concat('SELECT * FROM Sales WHERE OrderDate = ''', pipeline().parameters.LoadDate, '''')`,`SELECT * FROM Sales WHERE OrderDate = @pipeline().parameters.LoadDate`,`@{SELECT * FROM Sales WHERE OrderDate = pipeline().parameters.LoadDate}`,`@string('SELECT * FROM Sales WHERE OrderDate = ', pipeline().parameters.LoadDate)`],a:0,
 ex:`A dynamic expression starts with @ and builds the string with concat. Two single quotes escape one quote. String interpolation also works: SELECT ... = '@{pipeline().parameters.LoadDate}'. Option B isn't interpolated because the expression isn't wrapped in @{ }.`},
{s:1,d:1,t:"single",ref:"notebook base parameters parameter cell pipeline",
 stem:`A pipeline runs Notebook1 with a base parameter named region set to "North". The notebook's parameter cell sets region = "West". Which value does the notebook use at runtime?`,
 opts:["North","West","Both; the values are concatenated","The run fails because of the conflict"],a:0,
 ex:`Base parameters passed from the pipeline override the defaults defined in the cell that's toggled as the parameter cell.`},
{s:1,d:1,t:"build",ref:"deployment pipeline variable library active value set stages",
 stem:`You need to set up a deployment pipeline that uses a variable library so a Copy activity reads the right source in each stage. Which four actions should you perform in sequence? Move the appropriate actions to the answer area and arrange them in the correct order.`,
 pool:["Create the variable library with Dev, Test, and Prod value sets and reference its variables from the Copy activity","Create a deployment pipeline and assign TE-Dev, TE-Test, and TE-Prod to its stages","Deploy the pipeline and the variable library from Dev to Test","In TE-Test, open the deployed variable library and set the Test value set as active","Create a deployment rule that changes the active value set","Rename the Default value set to Test"],a:[0,1,2,3],
 ex:`Define the variables and value sets first, assign workspaces to stages, deploy, then activate the stage's value set once in the target workspace. Deployment rules don't control value sets, and the active set is chosen per workspace, not by renaming.`},
{s:1,d:2,t:"hot",ref:"Delta MERGE slowly changing dimension type 2 Spark SQL",
 stem:`You are implementing a Type 2 slowly changing dimension in Spark SQL. The first MERGE must expire the current row when the address changes. How should you complete the statement? Select the appropriate option in each list.`,
 tpl:`MERGE INTO dim_customer t
USING updates s
  ON t.customer_id = s.customer_id AND t.[[0]] = true
WHEN MATCHED AND t.address <> s.address THEN
  UPDATE SET t.is_current = [[1]], t.end_date = current_date();`,
 sel:[["is_current","is_deleted","end_date"],["false","true","null"]],a:[0,0],
 ex:`Match only the current version of each customer, then close it by setting is_current to false and stamping the end date. A second step inserts the new current row with a new surrogate key.`},
{s:1,d:2,t:"single",ref:"full load versus incremental load watermark",
 stem:`A 2-million-row source table has no reliable modified timestamp, no change tracking, and rows are updated in place. You need the lakehouse copy to be correct every morning with the least complexity. What should you implement?`,
 opts:["A nightly full load that overwrites the target table","A watermark-based incremental load on the primary key","An Eventstream with a CDC source","Mirroring"],a:0,
 ex:`Incremental loads need a reliable change indicator. Without one, a full overwrite of a 2-million-row table is simple and correct. A key-based watermark would miss in-place updates.`},
{s:1,d:2,t:"single",ref:"Eventhouse OneLake availability one logical copy",
 stem:`Meter events must be queryable with KQL within seconds and also readable as Delta tables by Spark, without maintaining a second ingestion path. What should you implement?`,
 opts:["An Eventstream to an Eventhouse with OneLake availability and a lakehouse shortcut","An Eventstream with both an Eventhouse destination and a lakehouse destination","Spark structured streaming to a Delta table, plus a shortcut in the KQL database","A Copy job that copies the Eventhouse table to the lakehouse every minute"],a:0,
 ex:`OneLake availability writes the KQL table's data to OneLake in Delta format, so Spark and SQL can read it through a shortcut. The other options ingest the same stream twice or add scheduled copies.`},
{s:1,d:2,t:"match",ref:"choose Dataflow Gen2 notebook KQL T-SQL transformation",
 stem:`Match each transformation scenario to the best engine. Each engine may be used once, more than once, or not at all.`,
 targets:["Analysts who know Power Query need to reshape a few million rows with no code","Custom Python logic over billions of rows","Stored procedures and MERGE statements in a warehouse","Time-series aggregation over a high-volume event table"],
 pool:["Dataflow Gen2","Notebook (PySpark)","T-SQL","KQL","Copy job","Apache Airflow job"],a:[0,1,2,3],
 ex:`Dataflow Gen2 is the low-code Power Query engine, PySpark handles code-heavy large-scale logic, T-SQL is the warehouse language, and KQL is built for time-series and event analytics.`},
{s:1,d:2,t:"yesno",ref:"OneLake shortcuts deletions Tables section Delta",
 stem:`For each statement about OneLake shortcuts, select Yes if it is true. Otherwise, select No.`,
 rows:["Deleting a file inside a shortcut folder deletes the file at the target when you have write permission there.","A shortcut whose name contains a space is recognized as a Delta table in the Tables section.","You can create a shortcut in a subfolder of the Tables section."],a:[1,0,0],
 ex:`Deleting the shortcut itself leaves the target alone, but deleting content through the shortcut deletes it at the target. Delta doesn't support spaces in table names, and Tables shortcuts can only be created at the top level.`},
{s:1,d:3,t:"single",ref:"manage shortcut connections replace connection lakehouse settings",
 stem:`The engineer who created the cloud connection used by 30 ADLS Gen2 shortcuts has left the company, and the shortcuts now fail. What should you do?`,
 opts:["Replace the connection from the lakehouse's Shortcut connections settings","Delete and recreate each of the 30 shortcuts using a new connection","Recreate the lakehouse from scratch and re-add each of the 30 shortcuts","Ask the tenant admin to transfer ownership of the user account"],a:0,
 ex:`The Manage OneLake shortcut connections page shows broken connections under Action required and lets you replace a connection once for every shortcut that uses it.`},
{s:1,d:2,t:"yesno",ref:"Fabric mirroring read-only open mirroring landing zone",
 stem:`For each statement about mirroring, select Yes if it is true. Otherwise, select No.`,
 rows:["Mirrored tables are stored in OneLake as Delta tables and can be queried through a SQL analytics endpoint.","You can modify mirrored tables with T-SQL INSERT and UPDATE statements.","Open mirroring lets your own application write change data to a landing zone that Fabric converts into mirrored Delta tables."],a:[1,0,1],
 ex:`Mirroring replicates source changes into read-only Delta tables; writes flow from the source only. Open mirroring extends mirroring to any application that can write to the landing zone format.`},
{s:1,d:2,t:"hot",ref:"PySpark join trunc countDistinct denormalize aggregate",
 stem:`You need to denormalize a fact table with its dimensions, keep fact rows even when a product is missing, and compute monthly sales and distinct customers per region. How should you complete the code? Select the appropriate option in each list.`,
 tpl:`flat = (fact.join(dim_product, "product_key", "[[0]]")
            .join(dim_store, "store_key", "left"))

agg = (flat.groupBy("region", F.[[1]]("order_date", "month").alias("month"))
           .agg(F.sum("amount").alias("sales"),
                F.[[2]]("customer_id").alias("customers")))`,
 sel:[["left","inner","right","cross"],["trunc","date_trunc","window"],["countDistinct","count","first"]],a:[0,0,0],
 ex:`A left join keeps unmatched fact rows. F.trunc(date, format) takes the column first; F.date_trunc(format, timestamp) takes the format first, so it wouldn't match this call. countDistinct counts unique customers.`},
{s:1,d:2,t:"hot",ref:"KQL arg_max ingestion_time late arriving data bin",
 stem:`Meters resend corrected readings up to a day late. You need the latest-arriving reading per meter per 15-minute window, then the average voltage per substation. How should you complete the KQL query? Select the appropriate option in each list.`,
 tpl:`Readings
| where Timestamp > ago(7d)
| summarize arg_max([[0]], *) by MeterId, bin(Timestamp, 15m)
| [[1]] AvgVolts = avg(Voltage) by SubstationId, [[2]]`,
 sel:[["ingestion_time()","Timestamp","Voltage"],["summarize","extend","project"],["bin(Timestamp, 15m)","MeterId","Voltage"]],a:[0,0,0],
 ex:`arg_max(ingestion_time(), *) keeps the row that arrived last for each meter and window, which is how late corrections win. A second summarize then aggregates by substation and the same window.`},
{s:1,d:2,t:"single",ref:"Spark structured streaming trigger availableNow checkpoint",
 stem:`A notebook must process all new files in Files/landing as a stream with exactly-once guarantees, then stop so the pipeline can continue. Which trigger should you use?`,
 opts:[`.trigger(availableNow=True) with a checkpointLocation`,`.trigger(processingTime="5 minutes") with a checkpointLocation`,`.outputMode("complete") with no trigger`,`.trigger(continuous="1 second")`],a:0,
 ex:`availableNow processes everything that's available in micro-batches and then stops, and the checkpoint tracks which files were processed. processingTime runs forever, and complete mode is for full aggregations.`},
{s:1,d:2,t:"single",ref:"Eventstream Expand operation array",
 stem:`Each event contains an array named readings. You need one row per array element before you aggregate. Which Eventstream operation should you add?`,
 opts:["Manage fields","Expand","Union","Join"],a:1,
 ex:`Expand flattens an array column into one row per element. Manage fields renames and casts columns, Union combines streams, and Join matches two streams.`},
{s:1,d:2,t:"yesno",ref:"Eventstream window types hopping snapshot session",
 stem:`For each statement about windowing in Eventstream, select Yes if it is true. Otherwise, select No.`,
 rows:["A hopping window with a size of 10 minutes and a hop of 5 minutes can assign one event to two windows.","A snapshot window groups events that have the same timestamp.","A session window has a fixed size."],a:[1,1,0],
 ex:`Hopping windows overlap when the hop is smaller than the size. Snapshot windows group events with identical timestamps. Session windows grow while events keep arriving and close after a period of inactivity.`},
{s:1,d:2,t:"single",ref:"query acceleration OneLake shortcut hot period Eventhouse cost",
 stem:`Five years of meter history exists as a Delta table in a lakehouse. Eventhouse users query the last 90 days often and older data rarely. You need fast queries on recent data with the least Eventhouse storage cost. What should you do?`,
 opts:["Create a OneLake shortcut with query acceleration and a 90-day hot period","Ingest the full table into a native KQL table in the Eventhouse","Create a standard OneLake shortcut without acceleration","Ingest the full table into KQL and set a 90-day retention policy on it"],a:0,
 ex:`Query acceleration indexes and caches only the hot window you define, so recent queries perform like native tables while older data stays in the lakehouse. A native copy stores everything twice, and a 90-day retention would discard history.`},
{s:1,d:3,t:"multi",n:2,ref:"Eventhouse materialized view caching policy optimize",
 stem:`A Real-Time Dashboard that shows hourly averages for the last 14 days is slow. The source table receives 20,000 events per second and has a 7-day hot cache. Which two actions should you perform? Each correct answer presents part of the solution.`,
 opts:["Create a materialized view of hourly averages","Extend the caching policy hot period to at least 14 days","Increase the retention policy on the table to 10 years","Disable OneLake availability on the source table","Run OPTIMIZE on the table after every ingestion batch"],a:[0,1],
 ex:`A materialized view maintains the aggregation continuously, and keeping the queried range in hot cache avoids reads from slower storage. Retention and OneLake availability don't affect query speed, and OPTIMIZE is a Delta command.`},
{s:1,d:3,t:"single",ref:"Eventstream deserialization errors runtime logs input format",
 stem:`An Eventstream shows incoming events, but the Eventhouse destination table stays empty. Workspace monitoring shows a rising count for Deserialization Errors on the source node. What is the most likely cause?`,
 opts:["The source's input data format doesn't match the incoming events","The Eventhouse caching policy is too short for the incoming data","The capacity that hosts the workspace is paused and rejecting events","The destination table has a retention policy of 0 days"],a:0,
 ex:`Deserialization errors mean the engine can't read incoming events because the format doesn't match the expected schema. Check the source node's Runtime logs and correct the input format.`},
{s:1,d:3,t:"hot",ref:".show ingestion failures Permanent Transient Eventhouse",
 stem:`Queued ingestion into an Eventhouse table is failing. You need the failures that won't succeed on retry and whether they came from an update policy. How should you complete the command? Select the appropriate option in each list.`,
 tpl:`.show [[0]] failures
| where FailureKind == "[[1]]"
| project Table, ErrorCode, Details, OriginatesFromUpdatePolicy`,
 sel:[["ingestion","streamingingestion","queries"],["Permanent","Transient"]],a:[0,0],
 ex:`.show ingestion failures lists queued ingestion failures with FailureKind Permanent or Transient. Permanent failures, such as a malformed CSV, won't succeed on retry. Streaming ingestion has its own .show streamingingestion failures command.`},
{s:1,d:3,t:"single",ref:"Direct Lake keep data up to date automatic updates suspended non-recoverable error",
 stem:`A Direct Lake semantic model has Keep your Direct Lake data up to date enabled, but reports show stale data since a refresh failed three days ago. What should you do first?`,
 opts:["Fix the cause of the failure and run an on-demand refresh","Convert the model to Import mode and schedule a refresh every hour","Disable and re-enable the Keep your Direct Lake data up to date setting","Run VACUUM on the source tables, then wait for the next automatic update"],a:0,
 ex:`Power BI suspends automatic updates after a non-recoverable refresh error. Automatic updates resume once a subsequent on-demand refresh completes without errors.`},
{s:1,d:3,t:"single",ref:"Direct Lake framing fails 10,000 parquet files guardrail",
 stem:`A Direct Lake refresh fails for a table whose Delta folder contains 25,000 Parquet files. What should you do?`,
 opts:["Run OPTIMIZE on the table to compact the files","Increase the semantic model's refresh timeout to four hours","Switch the table in the model to DirectQuery mode","Enable high concurrency mode for the refresh session"],a:0,
 ex:`Framing fails when a Delta table exceeds capacity guardrails, such as more than 10,000 Parquet files. Compacting with OPTIMIZE brings the file count down.`},
{s:1,d:3,t:"match",ref:"queryinsights runtime logs capacity metrics monitoring hub",
 stem:`Match each monitoring question to the tool that answers it. Each tool may be used once, more than once, or not at all.`,
 targets:["Which warehouse queries scanned the most remote storage in the last 30 days?","Why did the lakehouse destination of an Eventstream fail last night?","Is the capacity's 24-hour background percentage above the surge protection threshold?","Which notebooks ran in the workspace this week, and did they succeed?"],
 pool:["queryinsights views in the warehouse","Runtime logs on the Eventstream node","Capacity Metrics app","Monitoring hub","Purview audit log","Spark UI"],a:[0,1,2,3],
 ex:`queryinsights.exec_requests_history keeps per-query history. Eventstream Runtime logs show node-level errors. The Capacity Metrics app shows throttling and the background percentage. The Monitoring hub lists item runs across workspaces.`},
{s:1,d:3,t:"single",ref:"pipeline schedule failure notifications",
 stem:`An on-call engineer must receive an email whenever a scheduled pipeline run fails. What is the least-effort way to configure this?`,
 opts:["Add the engineer under Failure notifications on the pipeline's schedule","Create an Activator rule on workspace item events","Add an Office 365 Outlook activity on the failure path of every activity","Enable capacity throttling notifications"],a:0,
 ex:`Scheduled pipeline runs support failure notification recipients directly on the schedule. The other options work but need more configuration or notify about different things.`},
{s:1,d:3,t:"yesno",ref:"Fabric throttling interactive delay interactive rejection surge protection",
 stem:`For each statement about capacity throttling, select Yes if it is true. Otherwise, select No.`,
 rows:["Interactive delay throttling starts once the capacity has used up its CU resources for the next 10 minutes.","During interactive rejection, background operations such as scheduled refreshes can still start.","Surge protection stops background jobs that are already running."],a:[1,1,0],
 ex:`Throttling is progressive: 20-second interactive delays after 10 minutes of future usage, interactive rejection after 60 minutes, and rejection of everything after 24 hours. Background jobs run during interactive rejection. Surge protection rejects new background operations but never cancels in-progress jobs.`},
{s:1,d:3,t:"single",ref:"notebook ModuleNotFoundError environment library pipeline run",
 stem:`A notebook runs successfully when you run it interactively but fails in a pipeline with ModuleNotFoundError: No module named 'great_expectations'. What should you do?`,
 opts:["Add the library to the environment that's attached to the notebook","Increase the executor memory in the Spark pool","Enable high concurrency mode for pipelines that run notebooks","Add a retry to the Notebook activity with a 60-second interval"],a:0,
 ex:`%pip install in a cell affects only that session. Libraries that scheduled runs need must be in the environment attached to the notebook or set as the workspace default.`},
{s:1,d:3,t:"single",ref:"notebook default lakehouse deployment AnalysisException table not found",
 stem:`After you deploy a notebook from TE-Dev to TE-Test, the Notebook activity fails with AnalysisException: Table or view not found: silver.orders. The table exists in the Test lakehouse. What is the most likely cause?`,
 opts:["The default lakehouse still points to Dev; set it per stage with a deployment rule","The Spark session timed out while the notebook waited for the Test lakehouse to start","The executor memory is too low to read the silver.orders table in Test","The notebook needs high concurrency mode to share a session with the pipeline"],a:0,
 ex:`Table names resolve against the notebook's default lakehouse. After deployment it still points at LH_Dev, so silver.orders isn't found. Deployment rules or a variable library fix the binding per stage.`},
{s:1,d:3,t:"single",ref:"Dataflow Gen2 insufficient permissions for accessing staging artifacts",
 stem:`A Dataflow Gen2 refresh fails with: The dataflow refresh failed due to insufficient permissions for accessing staging artifacts. What is the cause?`,
 opts:["The creator of the workspace's first dataflow hasn't signed in for over 90 days or has left","Staging is disabled on the query that loads data to the warehouse destination","The destination lakehouse has OneLake security enabled with a row-level rule","Fast copy isn't enabled for the source connector in the dataflow's options"],a:0,
 ex:`The staging artifacts belong to the user who created the first dataflow in the workspace. That user must sign in again; if they left the organization, open a support ticket.`},
{s:1,d:3,t:"single",ref:"Fabric warehouse unsupported data types money datetime",
 stem:`CREATE TABLE dbo.Invoice (InvoiceId int, Amount money, IssuedOn datetime) fails in a Fabric warehouse. What should you change?`,
 opts:["Use decimal for Amount and datetime2 for IssuedOn","Add NOT ENFORCED to the InvoiceId column definition","Use nvarchar for Amount and varchar for the IssuedOn column","Create the table in the SQL analytics endpoint instead"],a:0,
 ex:`money, smallmoney, datetime, smalldatetime, datetimeoffset, nchar, nvarchar, text, and ntext aren't supported for warehouse tables. Use decimal, datetime2, and varchar.`},
{s:1,d:3,t:"single",ref:"OneLake security shortcut delegated identity mode SQL analytics endpoint fails",
 stem:`A SQL analytics endpoint in delegated identity mode queries a shortcut to a table in another lakehouse. The query fails. The source lakehouse has a OneLake security role with row-level security on that table. What should you do?`,
 opts:["Switch the endpoint to user identity mode instead of delegated identity mode","Grant the endpoint owner the Admin role on the source workspace","Recreate the shortcut in the Files section of the endpoint's lakehouse","Enable result set caching so the filtered rows are read from cache"],a:0,
 ex:`In delegated mode, shortcuts are blocked when the source table has OneLake RLS, CLS, or OLS, so filtered data can't leak through the owner's identity. User identity mode passes the caller to OneLake, or you move the filtering to SQL.`},
{s:1,d:3,t:"multi",n:2,ref:"Fabric warehouse data clustering result set caching",
 stem:`A dashboard runs the same aggregate query every minute against a 500-million-row warehouse table filtered by OrderDate. You need to cut capacity consumption. Which two actions should you perform? Each correct answer presents part of the solution.`,
 opts:["Apply data clustering on the OrderDate column","Keep result set caching enabled and remove GETDATE() from the query so the result can be reused","Create a clustered index on OrderDate","Disable V-Order on the warehouse","Add OPTION (USE HINT ('DISABLE_RESULT_SET_CACHE'))"],a:[0,1],
 ex:`Data clustering reduces the data scanned for selective predicates. Result set caching is on by default, but queries with runtime constants such as GETDATE() aren't cached. Fabric Warehouse has no user indexes, and disabling V-Order is irreversible and hurts reads.`},
{s:1,d:3,t:"single",ref:"lakehouse table maintenance optimize V-Order small files streaming",
 stem:`A streaming job appends to a Delta table every 30 seconds and produces thousands of small files. Reads are slow, and you can't change the writer. What should you do?`,
 opts:["Schedule OPTIMIZE with V-Order through the lakehouse table maintenance page","Run VACUUM RETAIN 0 HOURS on the table after each batch","Increase spark.sql.shuffle.partitions in the workspace Spark settings","Convert the table to CSV files so readers skip Delta metadata"],a:0,
 ex:`OPTIMIZE compacts small files into larger ones, and V-Order improves read performance. VACUUM removes only unreferenced files, and more shuffle partitions would create more files.`},
{s:1,d:3,t:"single",ref:"Fabric warehouse cold start data_scanned_remote_storage_mb cache",
 stem:`The first warehouse query each morning takes 40 seconds; the same query later takes 2 seconds. queryinsights shows a high data_scanned_remote_storage_mb value only for the first run. What is the cause?`,
 opts:["A cold start: data is loaded into cache on first access; no fix is required","Missing indexes on the table, so every query scans all the files","Result set caching is disabled on the warehouse, so each run recomputes the result","The table isn't V-Order optimized, so the first scan is slow"],a:0,
 ex:`Cold starts happen when data isn't cached yet, statistics are created, or paused nodes resume. In-memory and disk caching is automatic, so later runs are fast.`},
{s:1,d:2,t:"single",ref:"Copy job incremental copy change tracking Fabric Data Factory",
 stem:`You need to copy 80 tables from Azure SQL Database into a lakehouse every hour, moving only changed rows, with the least configuration. What should you use?`,
 opts:["A Copy job with incremental copy","A pipeline with a ForEach loop and 80 watermark lookups","A Dataflow Gen2 per table","An Eventstream per table"],a:0,
 ex:`Copy job provides built-in incremental copy and scheduling across many tables without writing watermark logic per table.`},
{s:1,d:2,t:"single",ref:"Eventstream Activator Teams alert threshold rule",
 stem:`Operations must receive a Teams message within one minute when any meter reports a voltage above 253 V. Events arrive through an Eventstream. What should you implement?`,
 opts:["Add an Activator destination and a Voltage rule with a Teams action","Add a lakehouse destination and schedule a notebook to run every minute","Create a KQL materialized view of Voltage and a Power BI alert on it","Add an Outlook activity to a pipeline that runs every minute"],a:0,
 ex:`Activator evaluates rules against streaming events as they arrive and can send Teams messages, which meets the one-minute requirement. Scheduled notebooks or Power BI alerts are periodic and slower.`},
{s:1,d:2,t:"single",ref:"Dataflow Gen2 Navigate using full hierarchy schema destination",
 stem:`A Dataflow Gen2 must write to the finance schema of a warehouse, but only dbo appears when you configure the destination. What should you do?`,
 opts:["Enable Navigate using full hierarchy on the connection","Enable fast copy for the query in the dataflow's Options dialog","Disable staging on the query that loads the finance table","Rename the finance schema to dbo so it appears in the list"],a:0,
 ex:`Schema support in lakehouse, warehouse, and SQL database destinations requires the Navigate using full hierarchy option on the connection.`},
{s:1,d:1,t:"single",ref:"Fabric workspace roles Viewer execution output service principal",
 stem:`Which statement about workspace roles is true?`,
 opts:["A Viewer can see pipeline and notebook output but can't run them","A Contributor can add other users to the workspace as Viewers","A Member can delete the workspace after removing others","A service principal can't be assigned to a workspace role"],a:0,
 ex:`Viewers can view execution output. Members can add users, but only Admins can delete or update the workspace. Service principals can be assigned to workspace roles and inherit the same permissions for API operations.`},

/* ===== Section 3: no-return series ===== */
{s:2,d:3,t:"series",grp:"A",ref:"Dataflow Gen2 fast copy transformations",
 scen:`A Dataflow Gen2 ingests 60 GB of Parquet files from Azure Data Lake Storage Gen2 into a lakehouse table. The query applies a Merge and a Group By transformation. The refresh takes three hours. You need to reduce the refresh time.`,
 sol:`Solution: You enable Allow use of fast copy connectors and keep the Merge and Group By transformations in the same query.`,a:1,
 ex:`Combining fast copy with transformations that don't fold disables fast copy for that query, so the refresh still runs on the slow path. Doesn't meet the goal.`},
{s:2,d:3,t:"series",grp:"A",ref:"Dataflow Gen2 fast copy staged query",
 scen:`A Dataflow Gen2 ingests 60 GB of Parquet files from Azure Data Lake Storage Gen2 into a lakehouse table. The query applies a Merge and a Group By transformation. The refresh takes three hours. You need to reduce the refresh time.`,
 sol:`Solution: You enable fast copy, split the work into one query that lands the raw data with staging enabled and a second query that references it, applies the transformations, and writes to the lakehouse.`,a:0,
 ex:`This is the recommended ELT pattern: fast copy moves the data with the pipeline Copy engine, and the transformations run on the staged data with Fabric compute. Meets the goal.`},
{s:2,d:3,t:"series",grp:"A",ref:"Dataflow Gen2 require fast copy",
 scen:`A Dataflow Gen2 ingests 60 GB of Parquet files from Azure Data Lake Storage Gen2 into a lakehouse table. The query applies a Merge and a Group By transformation. The refresh takes three hours. You need to reduce the refresh time.`,
 sol:`Solution: You disable staging on all queries and select Require fast copy on the query.`,a:1,
 ex:`Require fast copy stops the refresh when fast copy can't be used, and the non-folding transformations in the query still prevent it. The refresh would fail instead of getting faster.`},
{s:2,d:1,t:"series",grp:"B",ref:"Viewer read lakehouse table Spark OneLake security",
 scen:`User1 holds the Viewer role on Workspace1. User1 must read the Sales table in Lakehouse1 from a Spark notebook. User1 must not be able to create or modify any item in Workspace1.`,
 sol:`Solution: You share Lakehouse1 with User1 and select Read all data using SQL.`,a:1,
 ex:`That permission (ReadData) grants access only through the SQL analytics endpoint, not through Spark or OneLake. Doesn't meet the goal.`},
{s:2,d:1,t:"series",grp:"B",ref:"OneLake security role Read table Viewer",
 scen:`User1 holds the Viewer role on Workspace1. User1 must read the Sales table in Lakehouse1 from a Spark notebook. User1 must not be able to create or modify any item in Workspace1.`,
 sol:`Solution: You create a OneLake security role on Lakehouse1 that grants Read on the Sales table and add User1 as a member.`,a:0,
 ex:`OneLake security roles grant data access to Viewers and are enforced by Spark, while the Viewer role still prevents item changes. Meets the goal.`},
{s:2,d:1,t:"series",grp:"B",ref:"Contributor role write items least privilege",
 scen:`User1 holds the Viewer role on Workspace1. User1 must read the Sales table in Lakehouse1 from a Spark notebook. User1 must not be able to create or modify any item in Workspace1.`,
 sol:`Solution: You assign User1 the Contributor role on Workspace1.`,a:1,
 ex:`Contributors can read all data, but they can also create and edit items, which breaks the second requirement.`}
];

const SECTIONS=[
 {name:"Case study",desc:"Read the Tamarack Energy case on the left (tabs) and answer 8 questions. You can review answers before leaving the case, but you can't return afterward.",review:true},
 {name:"Questions",desc:"54 items: single and multiple answer, hot area (complete code or settings), build list (order steps), drag and drop (match), and yes/no statements. You can review and change answers until you leave the section.",review:true},
 {name:"Scenario series",desc:"Six items in two series. Each item restates the same scenario with a different solution. Answer Yes if the solution meets the goal. After you answer an item and select Next, you can't return to it.",review:false}
];
const MINUTES=100;


Q.forEach(q=>{if(q.s===0)q.c=0});return {CASES:[CASE],Q,SECTIONS};
}
